"""The committed characterization files are complete and consistent (they are regenerated by hand, see tests/characterization)."""
import importlib.util
import json
from pathlib import Path

import pytest

DIR = Path(__file__).parent / "characterization"
GOLDEN = DIR / "golden"


def _cases():
    spec = importlib.util.spec_from_file_location("zinet_characterization_cases", DIR / "cases.py")
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod.CASES


def _load(name):
    return json.loads((GOLDEN / f"{name}.json").read_text(encoding="utf-8"))


def test_cases_json_matches_cases_py():
    assert json.loads((DIR / "cases.json").read_text(encoding="utf-8")) == _cases()


def test_case_names_are_unique_and_inputs_are_well_formed():
    cases = _cases()
    assert len({c["name"] for c in cases}) == len(cases)
    for c in cases:
        ids = [n["id"] for n in c["nodes"]]
        assert len(ids) == len(set(ids)), c["name"]
        assert not set(ids) & set(c["primitives"]), c["name"]
        for q in c["queries"]:
            assert set(q) == {"known", "target"}


@pytest.mark.parametrize("source, sources_key", [("graph_code", "graph_code"), ("conceptbook_v1", "conceptbook"), ("conceptbook_v2", "conceptbook")])
def test_every_case_has_a_golden_result_for_each_source_it_applies_to(source, sources_key):
    golden = _load(source)
    assert "@" in golden["_source"]
    expected = {c["name"] for c in _cases() if sources_key in c.get("sources", ("graph_code", "conceptbook"))}
    assert set(golden["cases"]) == expected
    for case in _cases():
        if case["name"] not in expected:
            continue
        result = golden["cases"][case["name"]]
        for i in range(len(case["queries"])):
            assert f"learning_path_{i}" in result and f"gap_{i}" in result
        assert "acyclic" in result and "reducible" in result


def test_the_sources_are_pinned_to_the_behaviours_the_report_describes():
    """The root causes in divergences.md rest on these facts; if a source changes, regenerate and re-read the report."""
    gc, v1, v2 = (_load(n)["cases"] for n in ("graph_code", "conceptbook_v1", "conceptbook_v2"))
    assert gc["chain"]["gap_0"] == ["a", "b", "c", "z"]                 # includes the target, no primitives
    assert v1["chain"]["gap_0"] == ["a", "b", "c", "p"]                 # ancestors only, primitives included
    assert gc["foundation_concept"]["reducible"] is False and v1["foundation_concept"]["reducible"] is True
    assert gc["dangling"]["reducible"] is True and v1["dangling"]["reducible"] is False
    assert v1["listed_primitive"]["reducible"] is False and v2["listed_primitive"]["reducible"] is True
    assert gc["query_edges"]["learning_path_1"] == {"raises": "ToolFailed"}
    assert v1["query_edges"]["learning_path_1"] == {"raises": "NetworkXError"}


def test_roundtrip_golden_keeps_comments_and_reports_orphans():
    g = _load("workgraph_roundtrip")["cases"]["with_comments"]
    assert len(g["harvest"]) == 7 and g["harvest_is_stable"] is True and g["round_trip_orphans"] == []
    texts = [c["text"] for c in g["harvest"]]
    assert "A # inside quotes is not a comment" not in texts          # '#' inside quotes is data, not a comment
    removed = g["after_removing_b"]
    assert len(removed["orphans"]) == 3 and "# [orphaned from b] note on b's label" in removed["text"]
    assert _load("workgraph_roundtrip")["cases"]["unordered"]["dump_yaml"].splitlines()[3:6] == ["  - id: a", "    kind: file", "    label: A"]


def test_engine_golden_covers_every_bundled_workflow():
    g = _load("graphlang_engines")["cases"]
    assert {"self_refine", "build_concept_book", "code_pipeline"} <= set(g)
    cp = g["code_pipeline"]
    assert cp["mermaid"].startswith("flowchart LR") and "subgraph" in cp["mermaid"]
    assert 'subgraph "cluster_test_gated_loop"' in cp["dot"] and "fixedsize" not in cp["dot"] and "fixedsize=true" in cp["dot_fixed_size"]
    assert any(e["data"].get("parent") == "test_gated_loop" for e in cp["cytoscape_elements"])
    assert not any("position" in e for e in cp["cytoscape_elements"])
